import { beforeAll, beforeEach, describe, it } from 'bun:test'
import { TestApp } from '@guren/testing'
import app from '../src/app.js'
import { Post } from '../app/Models/Post.js'
import { User } from '../app/Models/User.js'

describe('Post slugs', () => {
  let http: TestApp
  let testUser: any

  beforeAll(async () => {
    http = await TestApp.fromApp(app)
  })

  beforeEach(async () => {
    // Create a test user
    testUser = await User.forceCreate({
      name: 'Test User',
      email: `test-${Date.now()}@example.com`,
      password: 'secret',
    })
  })

  it('generates slug from title when creating post', async () => {
    const csrf = await http.actingAs(testUser).withCsrf()
    await csrf
      .post('/posts', {
        title: 'Hello, World!',
        excerpt: 'This is a test',
        body: 'Test body',
      })
      .assertCreated()

    const post = await Post.first({ title: 'Hello, World!' })
    if (!post) throw new Error('Post not found')

    if (post.slug !== 'hello-world') {
      throw new Error(`Expected slug "hello-world", got "${post.slug}"`)
    }
  })

  it('generates unique slugs for posts with same title', async () => {
    const csrf = await http.actingAs(testUser).withCsrf()

    // Create first post
    await csrf
      .post('/posts', {
        title: 'Duplicate Title',
        excerpt: 'First',
        body: 'Test body 1',
      })
      .assertCreated()

    // Create second post with same title
    await csrf
      .post('/posts', {
        title: 'Duplicate Title',
        excerpt: 'Second',
        body: 'Test body 2',
      })
      .assertCreated()

    const posts = await Post.newQuery()
      .where('title', '=', 'Duplicate Title')
      .orderBy('id', 'asc')
      .get()

    if (posts.length !== 2) throw new Error(`Expected 2 posts, got ${posts.length}`)
    if (posts[0].slug !== 'duplicate-title') throw new Error(`First post slug should be "duplicate-title", got "${posts[0].slug}"`)
    if (posts[1].slug !== 'duplicate-title-2') throw new Error(`Second post slug should be "duplicate-title-2", got "${posts[1].slug}"`)
  })

  it('strips special characters from slug', async () => {
    const testCases = [
      { title: 'Hello & World!', expected: 'hello-world' },
      { title: '  Guren  &  Bun: 2026 Edition!  ', expected: 'guren-bun-2026-edition' },
      { title: 'Multiple---Dashes', expected: 'multiple-dashes' },
    ]

    for (const { title, expected } of testCases) {
      const slug = Post.generateSlug(title)
      if (slug !== expected) {
        throw new Error(`Expected slug "${expected}" for title "${title}", got "${slug}"`)
      }
    }
  })

  it('serves post page via slug URL', async () => {
    const post = await Post.forceCreate({
      title: 'Test Post',
      slug: 'test-post',
      excerpt: 'Test',
      body: 'Test body',
      authorId: testUser.id,
    })

    await http
      .get(`/posts/${post.slug}`)
      .assertOk()
      .assertInertia('posts/Show', { post: { slug: 'test-post', id: post.id } })
  })

  it('redirects numeric ID to slug URL with 301', async () => {
    const post = await Post.forceCreate({
      title: 'Redirect Test',
      slug: 'redirect-test',
      excerpt: 'Test',
      body: 'Test body',
      authorId: testUser.id,
    })

    await http
      .get(`/posts/${post.id}`)
      .assertStatus(301)
      .assertHeader('Location', `/posts/${post.slug}`)
  })

  it('returns 404 for non-existent slug', async () => {
    await http.get('/posts/nonexistent-slug').assertNotFound()
  })

  it('returns 404 for non-existent numeric ID', async () => {
    await http.get('/posts/99999').assertNotFound()
  })

  it('redirects to slug URL after creating post', async () => {
    const csrf = await http.actingAs(testUser).withCsrf()
    const response = await csrf
      .post('/posts', {
        title: 'Created Post',
        excerpt: 'Test',
        body: 'Test body',
      })

    const post = await Post.first({ title: 'Created Post' })
    if (!post) throw new Error('Post not found')

    if (!response.headers.has('Location')) throw new Error('Expected redirect')
    const location = response.headers.get('Location')
    if (location !== `/posts/${post.slug}`) {
      throw new Error(`Expected redirect to /posts/${post.slug}, got ${location}`)
    }
  })

  it('redirects to slug URL after updating post', async () => {
    const post = await Post.forceCreate({
      title: 'Original Title',
      slug: 'original-title',
      excerpt: 'Test',
      body: 'Test body',
      authorId: testUser.id,
    })

    const csrf = await http.actingAs(testUser).withCsrf()
    const response = await csrf
      .put(`/posts/${post.id}`, {
        title: 'Updated Title',
        excerpt: 'Updated',
        body: 'Updated body',
      })

    if (!response.headers.has('Location')) throw new Error('Expected redirect')
    const location = response.headers.get('Location')
    if (location !== `/posts/${post.slug}`) {
      throw new Error(`Expected redirect to /posts/${post.slug}, got ${location}`)
    }
  })

  it('includes slug in post resource data', async () => {
    const post = await Post.forceCreate({
      title: 'Resource Test',
      slug: 'resource-test',
      excerpt: 'Test',
      body: 'Test body',
      authorId: testUser.id,
    })

    const response = await http.get(`/posts/${post.slug}`).assertOk()

    // The inertia response should contain the slug
    // Verify by checking the inertia page props
    await http
      .get(`/posts/${post.slug}`)
      .assertInertia('posts/Show', { post: { slug: 'resource-test' } })
  })
})
EOF
